style.css:
@-moz-document url-prefix("https://web.roblox.com"), url-prefix("https://www.roblox.com") {
/* Navbar */
  .rbx-navbar, .rbx-header {
    background-color: #d5dfde !important;
    color: #3e3e3e !important;
    border-color: #d5dfde !important;
  }

  /* Search bar */
  .navbar-search, 
  .navbar-search input, 
  .navbar-search .new-dropdown-menu {
    background-color: #ffffff !important;
    border-radius: 5px !important;
    color: #3e3e3e !important;
  }

  /* PFP and profile sections */
  .avatar-card-image, 
  .profile-avatar-left, 
  .section-content {
    background: transparent !important;
    color: #202227 !important;
  }
  
  /* Profile creations */
  .slide-switcher .slide-item-container .slide-item-container-left {
    background-color: #f5d6db;
  }

  .slide-switcher.games {
    color: #202227;
    background:transparent !important;
  }

  /* Profile groups */
  .slide-switcher .slide-item-container .slide-item-container-left {
    background-color: #bec897 !important;
}
  .slide-switcher .slide-item-container .slide-item-container-right {
    background-color: #bec897 !important;
  }

  /* Profile collections */
.light-theme .layer {
    background-color: #bec897 !important;
}

  /* Profile border and active page */
  .profile-accoutrements-page {
    border: 1px solid #425938 !important;
  }

  .page-active {
    background-color: #425938 !important;
  }

  /* play button */
  .btn-common-play-game-lg {
    background-color: #b8c590 !important;
}
    
  /* play button hover */
   .btn-common-play-game-lg:hover, .light-theme .btn-common-play-game-lg:focus {
    background-color: #d1dbaa !important;
}

  /* Join event button */
  .btn-growth-xs {
    background-color: #eab7bb !important;
  }
  .btn-growth-xs:hover,
  .btn-growth-xs:focus {
    background-color: #f7d5dc !important;
  }

  /* Chat */
  .chat-container .chat-main .chat-header {
    background-color: #bec897 !important;
  }

  /* Avatar editor background */
  .avatar-back {
    background-image: url("https://i.imgur.com/qFmcbT0.png") !important;
  }

  /* Friend list */
  .avatar-card-container {
    background-color: #c1cfb6 !important;
  }

  /* Left column (sidebar) */
  .rbx-left-col {
    background-color: #d5dfde !important;
  }

/*Background*/
body, .content
   {
     background:transparent!important;
   }
.light-theme, .dark-theme, .nav-content
  {
     width: 100% !important;
     height: 100% !important;
     background-attachment: fixed !important;
     background-size: cover !important;
    background-image:url("data:image/jpeg;base64,") !important;
}
}
